import $ from 'jquery';

/*
 * jQuery Tabs plugin
 */
(function ($, $win) {
  'use strict';

  function Tabset($holder, options) {
    this.$holder = $holder;
    this.options = options;

    this.init();
  }

  Tabset.prototype = {
    init: function () {
      this.$tabLinks = this.$holder.find(this.options.tabLinks);

      this.setStartActiveIndex();
      this.setActiveTab();

      if (this.options.autoHeight) {
        this.$tabHolder = $(this.$tabLinks.eq(0).attr(this.options.attrib)).parent();
      }

      this.makeCallback('onInit', this);
    },

    setStartActiveIndex: function () {
      const $classTargets = this.getClassTarget(this.$tabLinks);
      let $activeLink = $classTargets.filter('.' + this.options.activeClass);
      const $hashLink = this.$tabLinks.filter('[' + this.options.attrib + '="' + location.hash + '"]');
      let activeIndex;

      if (this.options.checkHash && $hashLink.length) {
        $activeLink = $hashLink;
      }

      activeIndex = $classTargets.index($activeLink);

      this.activeTabIndex = this.prevTabIndex = activeIndex === -1 ? (this.options.defaultTab ? 0 : null) : activeIndex;
    },

    setActiveTab: function () {
      const self = this;

      this.$tabLinks.each(function (i, link) {
        const $link = $(link);
        const $classTarget = self.getClassTarget($link);
        let $tab = $();

        if (self.options.tabAttrib) {
          $tab = $('[' + self.options.tabAttrib + '="' + $link.attr(self.options.attrib) + '"]');
        } else {
          $tab = $($link.attr(self.options.attrib));
        }

        if (i !== self.activeTabIndex) {
          $classTarget.removeClass(self.options.activeClass);
          $tab.addClass(self.options.tabHiddenClass).removeClass(self.options.activeClass);
        } else {
          $classTarget.addClass(self.options.activeClass);
          $tab.removeClass(self.options.tabHiddenClass).addClass(self.options.activeClass);
        }

        self.attachTabLink($link, i);
      });
    },

    attachTabLink: function ($link, i) {
      const self = this;

      $link.on(this.options.event + '.tabset', function (e) {
        e.preventDefault();

        if (self.activeTabIndex === self.prevTabIndex && self.activeTabIndex !== i) {
          self.activeTabIndex = i;
          self.switchTabs();
        }

        if (self.options.checkHash) {
          location.hash = jQuery(this).attr('href').split('#')[1];
        }
      });
    },

    resizeHolder: function (height) {
      const self = this;

      if (height) {
        this.$tabHolder.height(height);

        setTimeout(function () {
          self.$tabHolder.addClass('transition');
        }, 10);
      } else {
        self.$tabHolder.removeClass('transition').height('');
      }
    },

    switchTabs: function () {
      const self = this;

      const $prevLink = this.$tabLinks.eq(this.prevTabIndex);
      const $nextLink = this.$tabLinks.eq(this.activeTabIndex);

      const $prevTab = this.getTab($prevLink);
      const $nextTab = this.getTab($nextLink);

      $prevTab.removeClass(this.options.activeClass);

      if (self.haveTabHolder()) {
        this.resizeHolder($prevTab.outerHeight());
      }

      setTimeout(
        function () {
          self.getClassTarget($prevLink).removeClass(self.options.activeClass);

          $prevTab.addClass(self.options.tabHiddenClass);
          $nextTab.removeClass(self.options.tabHiddenClass).addClass(self.options.activeClass);

          self.getClassTarget($nextLink).addClass(self.options.activeClass);

          if (self.haveTabHolder()) {
            self.resizeHolder($nextTab.outerHeight());

            setTimeout(function () {
              self.resizeHolder();
              self.prevTabIndex = self.activeTabIndex;
            }, self.options.animSpeed);
          } else {
            self.prevTabIndex = self.activeTabIndex;
          }

          self.makeCallback('onChange', self);
        },
        this.options.autoHeight ? this.options.animSpeed : 1
      );
    },

    getClassTarget: function ($link) {
      return this.options.addToParent ? $link.parent() : $link;
    },

    getActiveTab: function () {
      return this.getTab(this.$tabLinks.eq(this.activeTabIndex));
    },

    getTab: function ($link) {
      if (this.options.tabAttrib) {
        return $('[' + this.options.tabAttrib + '="' + $link.attr(this.options.attrib) + '"]');
      } else {
        return $($link.attr(this.options.attrib));
      }
    },

    haveTabHolder: function () {
      return this.$tabHolder && this.$tabHolder.length;
    },

    destroy: function () {
      const self = this;

      this.$tabLinks.off('.tabset').each(function () {
        const $link = $(this);

        self.getClassTarget($link).removeClass(self.options.activeClass);
        $($link.attr(self.options.attrib)).removeClass(self.options.activeClass + ' ' + self.options.tabHiddenClass);
      });

      this.$holder.removeData('Tabset');
    },

    makeCallback: function (name) {
      if (typeof this.options[name] === 'function') {
        const args = Array.prototype.slice.call(arguments);

        args.shift();
        this.options[name].apply(this, args);
      }
    },
  };

  $.fn.tabset = function (opt) {
    const args = Array.prototype.slice.call(arguments);
    const method = args[0];

    const options = $.extend(
      {
        activeClass: 'active',
        addToParent: false,
        autoHeight: false,
        checkHash: false,
        defaultTab: true,
        animSpeed: 500,
        tabLinks: 'a',
        attrib: 'href',
        tabAttrib: null,
        event: 'click',
        tabHiddenClass: 'js-tab-hidden',
      },
      opt
    );

    options.autoHeight = options.autoHeight;

    return this.each(function () {
      const $holder = jQuery(this);
      const instance = $holder.data('Tabset');

      if (typeof opt === 'object' || typeof opt === 'undefined') {
        $holder.data('Tabset', new Tabset($holder, options));
      } else if (typeof method === 'string' && instance) {
        if (typeof instance[method] === 'function') {
          args.shift();
          instance[method].apply(instance, args);
        }
      }
    });
  };
})($, $(window));
